{"results": [{"id": "hp_doc_3a9d6863e0a0e27779623116a704b7abdfa2c78b4e4f1dc3bab06a95a1985279", "title": "Free Democratic Party (Germany)", "text": "The Free Democratic Party (German: \"Freie Demokratische Partei\" , FDP) is a liberal and classical liberal political party in Germany. The FDP is led by Christian Lindner.", "score": 30.7034}, {"id": "hp_doc_5b7899fe24cda91e29926d6edff787dc2b350687364e50f8c4404421d7ef5700", "title": "Erich Mende", "text": "Dr. Erich Mende (28 October 1916 – 6 May 1998) was a German politician of the Free Democratic Party (FDP) and Christian Democratic Union (CDU). He was the leader of FDP from 1960 to 1968 and the third Vice-Chancellor of Germany (West Germany) from 1963 to 1966.", "score": 29.9871}, {"id": "hp_doc_183fa706b7af2cf0caca066aa49e240747a0b6d13dae2b76aab36358f98c2fe1", "title": "Klaus Kinkel", "text": "Klaus Kinkel (born 17 December 1936) is a German civil servant, lawyer, and politician of the liberal Free Democratic Party (FDP). He served as Federal Minister of Justice (1991–1992), Foreign Minister (1992–1998) and as Vice Chancellor of Germany (1993–1998) in the government of Helmut Kohl. He was also chairman of the liberal Free Democratic Party from 1993 to 1995. Previously, he was President of the Federal Intelligence Service (1979–1982).", "score": 23.3632}], "remaining_searches": 2}
